import csv, os, re
p = os.path.join(os.environ["PANTHEON_PROJECTS"], "crm/contacts.csv")
try: rows = list(csv.DictReader(open(p, newline="", encoding="utf-8-sig")))
except UnicodeDecodeError: rows = list(csv.DictReader(open(p, newline="", encoding="cp1252")))
print("columns", list(rows[0]), "rows", len(rows))
for r in rows[:5]: print(r)
for c in rows[0]:
    vals = [r[c] for r in rows]
    shapes = {re.sub(r"[0-9]", "9", re.sub(r"[A-Za-z]+", "a", v.strip())) for v in vals if v.strip()}
    print(c, "blanks", sum(not v.strip() for v in vals), "distinct", len(set(vals)), "shapes", sorted(shapes)[:6])

